const Advertisment=require("../models/advertismentModel"),handleErrors=require("../utilities/handle_errors")["handleErrors"],create_advertisment=async(t,d,e)=>{Advertisment.findOne({priority:t.body.priority,status:"active",advertiseAt:t.body.advertiseAt}).then(e=>{e?d.status(422).send({message:{en:"You already have that priority number on an active ad",ar:"لديك نفس الأولوية لاعلان نشط الان"}}):Advertisment.create(t.body).then(e=>{d.status(200).send(e)}).catch(e=>{d.status(422).send(handleErrors(e,t,"advertisment"))})})},get_advertisment=(e,d,a)=>{const s=e.query.page-1||0;Advertisment.find({$or:[{company:{$regex:e.query.company,$options:"i"},advertiseAt:{$regex:e.query.advertiseAt,$options:"i"}}]}).count().then(t=>{Advertisment.find({$or:[{company:{$regex:e.query.company,$options:"i"},advertiseAt:{$regex:e.query.advertiseAt,$options:"i"}}]}).sort({priority:1}).sort({createdAt:-1}).skip(16*s).limit(16).then(e=>d.status(200).send({advertisments:e,total_ads:t,per_page:16})).catch(a)})},get_single_advertisment=(e,t,d)=>{Advertisment.findById({_id:e.params.id}).then(e=>t.status(200).send(e)).catch(d)},delete_advertisment=(e,t,d)=>{Advertisment.findByIdAndDelete({_id:e.params.id}).then(e=>{t.status(200).send(e)}).catch(d)},update_advertisment=(t,d,a)=>{Advertisment.find({priority:t.body.priority,status:"active",advertiseAt:t.body.advertiseAt}).then(e=>{1<e.length||1==e.length&&"active"!=t.body.prevStatus?d.status(422).send({message:{en:"You already have that priority number on an active ad",ar:"لديك نفس الأولوية لاعلان نشط الان"}}):Advertisment.findByIdAndUpdate({_id:t.params.id},t.body).then(e=>{Advertisment.findOne({_id:t.params.id}).then(e=>d.status(200).send(e))}).catch(a)})},ad_clicked=(e,t,d)=>{Advertisment.findByIdAndUpdate({_id:e.params.id},{$inc:{clicks:1}}).then(e=>t.status(200).send(e)).catch(d)};module.exports={create_advertisment:create_advertisment,get_advertisment:get_advertisment,get_single_advertisment:get_single_advertisment,delete_advertisment:delete_advertisment,update_advertisment:update_advertisment,ad_clicked:ad_clicked};